#include <stdio.h>
#include <string.h>

int main() {
    long long x;
    if (scanf("%lld", &x) != 1) return 0;
    if (x < 0) {
        printf("false\n");
        return 0;
    }
    char s[64];
    sprintf(s, "%lld", x);
    int len = strlen(s);
    for (int i = 0; i < len / 2; i++) {
        if (s[i] != s[len - 1 - i]) {
            printf("false\n");
            return 0;
        }
    }
    printf("true\n");
    return 0;
}
